      move.reset();
      reassign.reset();
      deferral.reset();
      reminder.reset();
      redating.reset();
      proof.reset();
      commenting.reset();
      division.reset();
      inline.reset();
      setEditRefused(null);
      locking.reset();
      return reminder.mutateAsync(id);
    });
  };

  // The new date typed for each claim to re-date it to.
  const [redates, setRedates] = useState<Record<number, string>>({});

  const redating = useMutation({
