      move.reset();
      reassign.reset();
      deferral.reset();
      reminder.reset();
      redating.reset();
      proof.reset();
      commenting.reset();
      division.reset();
      inline.reset();
      setEditRefused(null);
      locking.reset();
      return move.mutateAsync({ id, action });
    });
  };

  const change = (patch: Partial<ClaimInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    save.reset();
  };

  const open = (c: Claim) => {
    move.reset();
    reassign.reset();
    deferral.reset();
    reminder.reset();
    redating.reset();
    proof.reset();
    commenting.reset();
    division.reset();
    inline.reset();
    locking.reset();
    if (c.status !== 'DRAFT') {
      setEditRefused({ id: c.id, message: `A ${c.status} claim cannot be edited. To change it, void it and add a new one.` });
      return;
    }
    if (periodOf(periods.data, c.dueBy)?.closed) {
