    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
  });

  const prove = (id: number) => {
    actOnce(() => {
      move.reset();
      reassign.reset();
      deferral.reset();
      reminder.reset();
      redating.reset();
      proof.reset();
      commenting.reset();
      division.reset();
      inline.reset();
      setEditRefused(null);
      locking.reset();
      return proof.mutateAsync(id);
    });
  };

  // The comment typed for each claim.
  const [commentTexts, setCommentTexts] = useState<Record<number, string>>({});

  const commenting = useMutation({
    mutationFn: (v: { id: number; text: string }) => commentClaim(sheetId, user, v.id, v.text),
    onSuccess: (_, v) => {
      setCommentTexts((t) => ({ ...t, [v.id]: '' }));
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  const comment = (id: number) => {
    const text = (commentTexts[id] ?? '').trim();
    actOnce(() => {
      move.reset();
      reassign.reset();
      deferral.reset();
      reminder.reset();
      redating.reset();
      proof.reset();
      commenting.reset();
      division.reset();
      inline.reset();
      setEditRefused(null);
      locking.reset();
      return commenting.mutateAsync({ id, text });
    });
  };

  const proofThreshold = useProofThreshold(sheetId);
  // Whether a claim needs a proof before it is settled or approved: none yet, and its due above the threshold.
  const needsProof = (c: Claim) => {
    const threshold = proofThreshold(gradeOn(c.date), c.date);
    const due = claimDue(c, rates, gradeOn, floor, charges);
    return c.proofs === 0 && threshold !== null && due !== null && Number(due) > Number(threshold);
  };

  const noteThreshold = useNoteThreshold(sheetId);
  // Whether a claim needs a note before it is opened: an empty one, and its due above the threshold.
  const needsNote = (c: Claim) => {
    const threshold = noteThreshold(c.date);
    const due = claimDue(c, rates, gradeOn, floor, charges);
    return (c.note ?? '').trim() === '' && threshold !== null && due !== null && Number(due) > Number(threshold);
  };

  const reassign = useMutation({
    mutationFn: (v: { id: number; to: number }) => reassignClaim(sheetId, user, v.id, v.to),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
  });

  const moveTo = (id: number) => {
    const to = Number(targets[id] ?? others[0]?.id ?? NaN);
    actOnce(() => {
      move.reset();
      reassign.reset();
      deferral.reset();
      reminder.reset();
      redating.reset();
      proof.reset();
      commenting.reset();
      division.reset();
      inline.reset();
      setEditRefused(null);
      locking.reset();
      return reassign.mutateAsync({ id, to });
    });
  };

  const act = (id: number, action: ClaimAction) => {
    actOnce(() => {
      move.reset();
      reassign.reset();
      deferral.reset();
      reminder.reset();
      redating.reset();
      proof.reset();
      commenting.reset();
      division.reset();
      inline.reset();
      setEditRefused(null);
      locking.reset();
      return move.mutateAsync({ id, action });
    });
  };

  const change = (patch: Partial<ClaimInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    save.reset();
  };

  const open = (c: Claim) => {
    move.reset();
    reassign.reset();
    deferral.reset();
    reminder.reset();
    redating.reset();
    proof.reset();
    commenting.reset();
    division.reset();
    inline.reset();
    locking.reset();
    if (c.status !== 'DRAFT') {
      setEditRefused({ id: c.id, message: `A ${c.status} claim cannot be edited. To change it, void it and add a new one.` });
      return;
    }
    if (periodOf(periods.data, c.dueBy)?.closed) {
      setEditRefused({ id: c.id, message: 'A claim due by a day inside a closed period cannot be edited.' });
      return;
    }
    if (c.lockedBy !== null && c.lockedBy !== undefined && c.lockedBy !== user) {
      setEditRefused({ id: c.id, message: `${c.lockedBy} is editing this claim; it cannot be edited until they save or cancel.` });
      return;
    }
    setEditRefused(null);
    setForm({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '', ref: c.ref ?? '', tags: showTags(c.tags) });
    setEditing(c.id);
    save.reset();
    locking.mutate(c.id);
  };

  const cancel = () => {
    const id = editing;
    setForm(EMPTY);
    setEditing(null);
    save.reset();
    locking.reset();
    setEditRefused(null);
    if (id !== null) unlocking.mutate(id);
  };

  return (
    <div>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const v = { id: editing, input: form };
          submitOnce(() => {
            save.reset();
            return save.mutateAsync(v);
          });
        }}
export function listClaims(sheetId: string): Promise<Claim[]> {
  return getJson<Claim[]>(`${sheetBase(sheetId)}/claims`);
}

/** Add a claim to a person; refused (rejects) when the amount is missing or has more than two
 *  decimals, the date is not a date, or it is a correction (negative) that does not name by number a
 *  SETTLED claim of the person, or its reference is already used on the sheet (in any case). A blank date takes the sheet's entry date when set, else its today. */
export function addClaim(sheetId: string, by: string, personId: number, input: ClaimInput): Promise<Claim> {
  return postJson<Claim>(`${sheetBase(sheetId)}/people/${personId}/claims?by=${encodeURIComponent(by)}`, input);
}

/** Edit a claim; refused (rejects) like an add. */
export function updateClaim(sheetId: string, by: string, id: number, input: ClaimInput): Promise<Claim> {
  return putJson<Claim>(`${sheetBase(sheetId)}/claims/${id}?by=${encodeURIComponent(by)}`, input);
}

